edits:
/* The hosted workspace contributes one document surface, not a second IDE shell. */
body.binary-hosted{background:#1e1e1e;color:#ddd;font:12px system-ui;display:grid;grid-template-rows:auto 1fr;height:100vh;overflow:hidden}
.binary-hosted>header,.binary-hosted>footer,.binary-hosted .boundary,.binary-hosted .runner>iframe,.binary-hosted .diagnostics{display:none}
.binary-hosted .toolbar{padding:7px 10px;gap:10px;border-radius:0;background:#252526;flex-wrap:wrap;font-size:11px}
.binary-hosted .toolbar label{gap:3px}.binary-hosted .toolbar input,.binary-hosted .toolbar select,.binary-hosted .toolbar button{padding:5px 8px;border-radius:2px;font-size:11px;height:27px;background:#333337;color:#ddd;border-color:#454548}
.binary-hosted .toolbar input[type=checkbox]{height:14px;width:14px}.binary-hosted main{padding:0;display:grid;grid-template-columns:200px minmax(150px,1fr) 275px;grid-template-rows:minmax(0,1fr);min-height:0;gap:1px;background:#414145}
.binary-hosted aside,.binary-hosted .code,.binary-hosted .runner{background:#1e1e1e;border:0;border-radius:0;min-height:0;overflow:auto;padding:10px}.binary-hosted aside{background:#252526;padding-top:0}
.binary-hosted h2{font-size:11px;padding:9px 0}.binary-hosted .code{display:grid;grid-template-rows:auto minmax(0,1fr) auto;padding:0;overflow:hidden}.binary-hosted .code nav{background:#2d2d30;padding:0;gap:0;flex-wrap:wrap;border-bottom:1px solid #444}
.binary-hosted .code nav button{background:transparent;padding:8px 10px;border-radius:0;font-size:11px}.binary-hosted .code nav button.selected{background:#1e1e1e;border-top:2px solid #bd9be8;padding-top:6px}
.binary-hosted textarea,.binary-hosted #listing{width:100%;height:100%;min-height:0;resize:none;margin:0;padding:14px;box-sizing:border-box;tab-size:4;font:12px/20px ui-monospace,monospace;border:0;border-radius:0;background:#1e1e1e;color:#ddd}
.binary-hosted .source-status{padding:5px 10px;font-size:10px}.binary-hosted .runner{background:#252526}.binary-hosted .runner-title{padding:0 0 12px;font-size:11px}
.binary-hosted .runner input,.binary-hosted .runner select,.binary-hosted .runner button,.binary-hosted .method-item{padding:7px;border-radius:2px;font-size:11px;background:#333337;color:#ddd;border-color:#454548;min-width:0;max-width:100%}.binary-hosted .runner button.primary{background:#59477a}
.binary-hosted #result{background:#1e1e1e;padding:12px;font-size:12px;min-height:130px;border:1px solid #444}.binary-hosted #symbol-path{grid-row:3;font:11px system-ui;padding:5px;overflow-wrap:anywhere}.binary-hosted:has(#symbol-path:not([hidden])) .source-status{display:none}
.binary-hosted #symbol-listing{grid-row:2}.binary-hosted [hidden]{display:none!important}
body.binary-hosted.light{color:#222;background:#fff}.binary-hosted.light aside,.binary-hosted.light .runner,.binary-hosted.light .toolbar{background:#f3f3f3;color:#222}.binary-hosted.light textarea,.binary-hosted.light #listing,.binary-hosted.light #result{background:#fff;color:#222}
@media(max-width:900px){.binary-hosted main{grid-template-columns:150px minmax(150px,1fr) 200px}.binary-hosted .toolbar>label:nth-of-type(2){display:none}}
@media(max-width:600px){.binary-hosted main{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(180px,1fr) auto}.binary-hosted aside{display:none}.binary-hosted .runner{max-height:180px}.binary-hosted .runner>label,.binary-hosted .runner>input{display:none}}
